def solve(n, edges):
    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)

        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    parent = []
    rank = []

    for node in range(n):
        parent.append(node)
        rank.append(0)

    for u, v in edges:
        union(parent, rank, u, v)

    components = set(find(parent, i) for i in range(n))
    return len(components)
