from typing import List

class UnionFind:
    def __init__(self, num: int):
        self.num = num
        self.parents = list(range(self.num))

    def find(self, n):
        if n != self.parents[n]:
            self.parents[n] = self.find(self.parents[n])
        return self.parents[n]

    def union(self, c1, c2):
        c1_root = self.find(c1)
        c2_root = self.find(c2)
        if c1_root != c2_root:
            self.parents[c2_root] = c1_root
            return True
        return False

def solve(num: int, edges: List[List[int]]) -> int:
    g = UnionFind(num)

    ans = num

    for a, b in edges:
        if g.union(a, b):
            ans -= 1

    return ans

