class UnionFind:
    def __init__(self, n):
        self.root = list(range(n))  # 初始状态下每个节点都是自己的根
        self.size = [1] * n         # 每个节点开始时的集合大小为1
        self.count = n              # 初始连通分量数量

    def find(self, x):
        """查找元素 x 所属的集合，同时进行路径压缩"""
        if self.root[x] != x:
            self.root[x] = self.find(self.root[x])
        return self.root[x]

    def union(self, x, y):
        """将元素 x 和 y 所属的两个集合合并"""
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False  # 同一集合，无需合并
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx  # 保持较小的树成为较大的树的子树
        self.root[ry] = rx   # 分别将两个集合的根指向较大的那个
        self.size[rx] += self.size[ry]  # 更新合并后根节点下集合的元素总数
        self.count -= 1     # 连通分量数量减一
        return True         # 成功合并

    def get_count(self):
        """返回当前图中的连通分量数目"""
        return self.count

def solve(n, edges):
    uf = UnionFind(n)  # 创建一个 UnionFind 结构，节点编号从 0 到 n-1
    for u, v in edges:
        uf.union(u, v)  # 遍历每条边，尝试合并对应的两个节点所在的集合
    return uf.get_count()  # 返回最终的连通分量数量
