import random

def solve(nums, k):
    """Returns the k-th smallest value n linux.
    """
    def partition(left, right):
        """Partitions nums[left] to nums[right] into two parts divided by nums[right].
        """
        pivot = nums[right]
        i = left - 1
        for j in range(left, right):
            if nums[j] <= pivot:
                i += 1
                nums[i], nums[j] = nums[j], nums[i]
        nums[i + 1], nums[right] = nums[right], nums[i + 1]
        return i + 1

    def quickselect(left, right, k):
        """Selects the k-th smallest element in nums[left] to nums[right].
        """
        if right - left <= 15:
            nums[left:right] = sorted(nums[left:right])
            return left + k - 1
        pivot_index = random.randint(left, right)
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        pivot_index = partition(left, right)
        if pivot_index == left + k - 1:
            return pivot_index
        elif pivot_index < left + k - 1:
            return quickselect(pivot_index + 1, right, k - (pivot_index - left + 1))
        else:
            return quickselect(left, pivot_index - 1, k)

    return quickselect(0, len(nums) - 1, k)[0]

