import re

class TableColumnClassifier:
    def __init__(self):
        self.table_columns = {}

    def set_table_columns(self, table_columns):
        self.table_columns = table_columns

    def extract_table_columns(self, table_content):
        columns = re.findall(r'\~.*?\|', table_content)
        if columns:
            self.table_columns = {column.strip():None for column in columns}
        else:
            return False
        return True

    def assign_value_to_table_columns(self, column, value):
        self.table_columns[column] = value

    def split_text_into_table_row(self, text):
        lines = text.split('\n')
        table_row = []
        for line in lines:
            split_line = line.split('\~')
            for cell in split_line:
                cell_value = cell.strip()
                matching_column = next((col for col in self.table_columns if cell_value in col), None)
                if matching_column is not None:
                    table_row.append(self.table_columns[matching_column])
                else:
                    table_row.append(cell_value)
        return table_row
