import heapq
import sys

def dijkstra(graph, start, end):
    """Dijkstra's algorithm to find the shortest path in a directed weighted graph."""
    # Initialize distances
    distances = {node: sys.maxsize for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we have already found a better path, skip
        if current_distance > distances[current_node]:
            continue

        # Visit each neighboring node
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path is found, update the distance and push to the queue
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances[end] if distances[end] != sys.maxsize else -1

def build_graph(n, edges):
    """Build the graph from the list of edges."""
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))
    return graph

def solve(n, edges, s, t):
    """Return the length of the shortest path from node s to node t."""
    if s == t:
        return 0
    graph = build_graph(n, edges)
    return dijkstra(graph, s, t) if s in graph else -1
