def solve(grid, start, goal, avoid=None):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_free(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def move(row, col, direction):
        if direction == 'up':
            return row - 1, col
        elif direction == 'down':
            return row + 1, col
        elif direction == 'left':
            return row, col - 1
        elif direction == 'right':
            return row, col + 1

    def dfs(row, col, path, visited):
        if (row, col) == goal:
            return [path]
        visited.add((row, col))
        directions = ['up', 'down', 'left', 'right']
        paths = []
        for direction in directions:
            new_row, new_col = move(row, col, direction)
            if is_free(new_row, new_col) and (new_row, new_col) not in visited:
                new_path = [(new_row, new_col)]
                for sub_path in dfs(new_row, new_col, new_path, visited):
                    paths.append([*path, *sub_path])
        return paths

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if avoid is not None and is_free(*avoid):
        return []

    visited = set()
    paths = dfs(start[0], start[1], [(start[0], start[1])], visited)
    return paths[0] if paths else []
