            if grid_list[r][c] != '#':
                neighbors.append([(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)])
            else:
                neighbors.append([])

    # Create a dictionary to store the parent of each cell
    parents = {}
    for i in range(rows * cols):
