import heapq

def solve(grid, start, goal):
    m, n = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    if start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        return path[::-1]

    visited = {start}
    queue = [(0, start)]

    while queue:
        cost, current = heapq.heappop(queue)
        if current == goal:
            return reconstruct_path(visited, current)

        for d in directions:
            next_r, next_c = current[0] + d[0], current[1] + d[1]
            if 0 <= next_r < m and 0 <= next_c < n:
                if grid[next_r][next_c] != '#' and (next_r, next_c) not in visited:
                    visited.add((next_r, next_c))
                    heapq.heappush(queue, (cost + 1, (next_r, next_c)))

    return []

