import collections

def solve(grid, start, goal):
    N, M = len(grid), len(grid[0])

    if grid[start[0]][start[1]] == "#" or grid[goal[0]][goal[1]] == "#":
        return []

    if start == goal:
        return [start]

    def get_next(r, c):
        for dr, dc in (1, 0), (-1, 0), (0, 1), (0, -1):
            R, C = r + dr, c + dc
            if 0 <= R < N and 0 <= C < M and grid[R][C] != "#":
                yield R, C

    que = collections.deque()
    seen = set()

    que.append((start, [start]))
    seen.add(start)

    while que:
        (cR, cC), frm = que.popleft()

        if (cR, cC) == goal:
            return frm

        for nR, nC in get_next(cR, cC):
            if (nR, nC) not in seen:
                que.append(((nR, nC), frm + [(nR, nC)]))
                seen.add((nR, nC))

