    visited.add(start)

    # Perform a depth-first search on the grid.
    while stack:
        # Get the next position to visit from the stack.
        pos = stack.pop()

        # If the current position is the goal position, return the path
        # from the start position to the goal position.
        if pos == goal:
            return [start]

        # Get the row and column indices of the current position.
        row, col = pos

        # Check the neighboring positions of the current position.
        for r, c in [(row+1, col), (row-1, col), (row, col+1), (row, col-1)]:
